{"cards": [{"node_code": "N_aa2b26f9d6c383e6", "definition": "涵盖地铁系统的日常行车组织、客运服务、票务管理、调度指挥，以及基于信息技术的运营自动化系统（如ATS、AFC）与综合管理策略。", "boundary": "本节点聚焦于地铁建成后的“运营”与“管理”环节。边界在于区分“运营”与“建设”（施工归入地铁施工节点）、“运营”与“设备维护”（硬件故障修复归入养护维修节点）。若内容涉及信号系统的具体硬件技术，归入通信信号节点；若涉及运营层面的信号调度逻辑与自动化控制，归入本节点。", "includes": ["地铁行车组织、调度指挥及客运服务管理", "票务系统、客流分析及运营经济评价", "运营自动化系统（ATS）及综合监控系统（ISCS）的应用"], "excludes": ["地铁线路、车站及车辆的基础设施建设与施工", "车辆、信号、供电等设备的机械故障维修与保养"], "sibling_distinctions": [{"other_code": "N_50e0c73d1f4209ac", "rule": "区分依据为工作性质：本节点侧重“使用”与“组织”，即如何高效、安全地运行系统；养护维修侧重“维护”与“修复”，即保持设备完好状态。"}, {"other_code": "N_200a30a96c0061c1", "rule": "区分依据为层级：自动控制侧重底层设备（如车辆、信号）的自动执行与控制逻辑；运营管理自动化侧重上层调度、监控及业务流程的自动化整合。"}], "cross_boundary_rule": "若内容涉及“信号系统”本身的技术原理，主挂载通信信号节点；若涉及信号系统在运营调度中的自动化应用（如自动进路），主挂载本节点。"}, {"node_code": "N_50e0c73d1f4209ac", "definition": "涵盖地铁基础设施、车辆、机电设备及通信信号系统的日常检查、预防性维护、故障修复、大修及更新改造技术与策略。", "boundary": "本节点聚焦于地铁系统的“全生命周期维护”。边界在于区分“养护维修”与“运营”（运营侧重服务提供，维修侧重设备状态保持）、“养护维修”与“施工”（新建工程归施工，既有设施修复归本节点）。若内容涉及车辆制造技术，归入车辆节点；若涉及车辆运用中的检修，归入本节点。", "includes": ["轨道、隧道、车站土建结构的检测与修复", "车辆、供电、通信信号等机电设备的检修、保养与大修", "维护管理体系、状态监测技术及备件管理"], "excludes": ["地铁新建线路、车站及车辆的首次安装与调试（归入施工或对应设备节点）", "地铁运营组织、调度指挥及客运服务管理"], "sibling_distinctions": [{"other_code": "N_aa2b26f9d6c383e6", "rule": "区分依据为对象与目的：本节点针对“设备与设施”的物理状态维护；运营管理针对“服务与流程”的组织效率。"}, {"other_code": "N_d82f3ab3ebca989d", "rule": "区分依据为工程阶段：施工节点涵盖新建、改建、扩建的工程实施；养护维修节点涵盖建成后的日常维护与故障处理。"}], "cross_boundary_rule": "若内容涉及“车辆制造”工艺，主挂载车辆节点；若涉及“车辆运用检修”规程，主挂载本节点。若涉及“隧道结构加固”作为新建工程的一部分，归施工；若作为既有隧道病害处理，归本节点。"}, {"node_code": "N_2b59929e274a9cae", "definition": "涵盖地铁地下空间火灾预防、探测报警、灭火系统、防排烟设计、应急疏散策略及消防安全管理体系。", "boundary": "本节点特指地铁系统的“消防安全”。边界在于区分“防火”与“通风”（通风系统若主要服务于日常环境控制归通风节点，若主要服务于火灾排烟归本节点或交叉）、“防火”与“运营”（日常运营安全归运营，火灾应急专项归本节点）。若内容涉及通用建筑防火规范，需结合地铁特殊性判断。", "includes": ["地铁火灾探测、报警及灭火系统（气体、水喷雾等）", "地下车站与隧道防排烟系统设计及运行", "火灾应急预案、疏散模拟及消防安全管理"], "excludes": ["地铁日常行车安全、设备故障处理（归入运营或养护维修）", "非火灾类的自然灾害（如洪水、地震）防护（若树中有独立节点则归入，否则视具体技术归属）"], "sibling_distinctions": [{"other_code": "N_eb900a20272fba2e", "rule": "区分依据为功能场景：通风节点侧重日常空气环境调节（温湿度、CO浓度）；防火节点侧重火灾状态下的排烟、控温及人员疏散。"}, {"other_code": "N_aa2b26f9d6c383e6", "rule": "区分依据为管理范畴：运营节点涵盖整体安全管理体系；防火节点聚焦于火灾这一特定风险源的预防、应对及管理。"}], "cross_boundary_rule": "若内容涉及“通风空调系统”在火灾模式下的联动控制，主挂载本节点（防火）；若涉及日常模式下的通风参数优化，主挂载通风节点。"}]}
